import { serve } from 'https://deno.land/std@0.208.0/http/server.ts';
import { createClient, SupabaseClient } from 'https://esm.sh/@supabase/supabase-js@2.45.4';

// ---- _shared/supabase.ts -------------------------------------
function getServiceClient(): SupabaseClient {
  return createClient(
    Deno.env.get('SUPABASE_URL') ?? '',
    Deno.env.get('SUPABASE_SERVICE_ROLE_KEY') ?? '',
  );
}

/**
 * Connection string for functions that talk raw Postgres (deno-postgres / pg).
 * At 1000+ tenants you MUST go through Supavisor in TRANSACTION mode (port 6543)
 * so a burst of concurrent functions doesn't exhaust backend connections.
 * Set SUPABASE_DB_POOL_URL to the "Transaction pooler" URI from
 * Dashboard -> Project Settings -> Database. Falls back to the direct URL.
 * RLS in v2 reads the JWT (no session GUCs) so transaction pooling is safe.
 */
function getPooledConnectionString(): string {
  return (
    Deno.env.get('SUPABASE_DB_POOL_URL') ??
    Deno.env.get('SUPABASE_DB_URL') ??
    ''
  );
}

function corsHeaders(origin = '*') {
  return {
    'Access-Control-Allow-Origin': origin,
    'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-tenant-id, x-environment',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, DELETE, OPTIONS',
  };
}

function jsonResponse(data: unknown, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { ...corsHeaders(), 'Content-Type': 'application/json' },
  });
}

function errorResponse(message: string, status = 400) {
  return jsonResponse({ error: message }, status);
}

// resolveTenantContext (trusted X-Tenant-Id) and validateApiKey (prefix-only check) were
// removed in Phase 0 (SEC-02 / SEC-04). Use _shared/auth.ts for signed-in users, or
// _shared/ingest-auth.ts (API keys via verify_api_key, site keys via resolve_ingest_site).

// ---- _shared/auth.ts -----------------------------------------
// Shared caller authentication for edge functions (Phase 0, SEC-01).
//
// Rule (docs/cpo/09-security-baseline.md §2): a function derives tenant access
// from a VERIFIED credential, never from a header or body. For calls made by a
// signed-in app user, the safest pattern is to act AS that user: queries run
// through a client carrying the user's JWT, so Postgres RLS enforces tenant
// isolation even if function code has a bug. Use the service role only after
// authentication, and only for work RLS can't express.


class AuthError extends Error {
  status: number;
  constructor(status: number, message: string) {
    super(message);
    this.status = status;
  }
}

type AuthedUser = {
  userId: string;
  email: string | null;
  /** Client that runs every query as the caller — RLS applies. */
  db: SupabaseClient;
};

const AUTH_UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

function requireEnv(name: string): string {
  const v = Deno.env.get(name);
  if (!v) throw new AuthError(500, `Server misconfigured: ${name} is not set`);
  return v;
}

/** Verify the bearer token belongs to a real signed-in user (not the anon key). */
async function authenticateUser(req: Request): Promise<AuthedUser> {
  const header = req.headers.get('authorization') ?? '';
  const token = header.startsWith('Bearer ') ? header.slice(7).trim() : '';
  if (!token) throw new AuthError(401, 'Not signed in');

  const db = createClient(requireEnv('SUPABASE_URL'), requireEnv('SUPABASE_ANON_KEY'), {
    global: { headers: { Authorization: `Bearer ${token}` } },
    auth: { persistSession: false, autoRefreshToken: false },
  });

  // getUser validates signature + expiry with Auth; the anon key has no user and fails here.
  const { data, error } = await db.auth.getUser(token);
  if (error || !data?.user) throw new AuthError(401, 'Session is invalid or expired');

  return { userId: data.user.id, email: data.user.email ?? null, db };
}

/** Confirm the caller is an active member of the tenant (checked by the database as the caller). */
async function requireTenantMember(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (typeof tenantId !== 'string' || !AUTH_UUID_RE.test(tenantId)) throw new AuthError(400, 'tenant_id must be a UUID');
  const { data, error } = await user.db.rpc('user_has_tenant_access', { p_tenant_id: tenantId });
  if (error) {
    console.error('tenant membership check failed', error.message);
    throw new AuthError(500, 'Could not verify tenant access');
  }
  if (data !== true) throw new AuthError(403, 'No access to this tenant');
  return tenantId.toLowerCase();
}

/** Tenant named by the caller (membership verified), or the caller's own active membership. */
async function resolveTenant(user: AuthedUser, tenantId: unknown): Promise<string> {
  if (tenantId !== undefined && tenantId !== null && tenantId !== '') return requireTenantMember(user, tenantId);
  const { data, error } = await user.db.from('tenant_users').select('tenant_id')
    .eq('user_id', user.userId).eq('status', 'active').order('created_at').limit(1);
  if (error) throw new AuthError(500, 'Could not resolve your workspace');
  const t = data?.[0]?.tenant_id as string | undefined;
  if (!t) throw new AuthError(403, 'You are not a member of any workspace');
  return t;
}

/** Throws 403 unless the caller holds `permission` in the tenant (tenant admins hold all). */
async function requirePermission(user: AuthedUser, tenantId: string, permission: string, label?: string): Promise<void> {
  const { data, error } = await user.db.rpc('user_has_permission', { p_tenant_id: tenantId, p_permission: permission });
  if (error) throw new AuthError(500, 'Could not verify permissions');
  if (data !== true) throw new AuthError(403, `You need the "${label ?? permission}" permission for this`);
}

// ---- _shared/ingest-auth.ts ----------------------------------
// Authentication for PUBLIC ingest endpoints (Phase 0, SEC-02).
//
// Two credential types — tenant/environment always come from the credential, never the request:
//   • Secret API key (server-to-server): `x-api-key: mk_…` or `Authorization: Bearer mk_…`.
//     Verified by public.verify_api_key() (bcrypt). Must carry the required scope.
//   • Site key (browser SDKs): body `site_id` + `write_key` (public by design, like a
//     Segment write key). Verified by public.resolve_ingest_site(): key, site status and
//     the browser Origin against the site's domain / allowed_origins.
//
// Because a site key is public, it can be copied and replayed from a script. Defences:
// per-site + per-IP rate limits here (per isolate — a backstop), frequency caps at send
// time (Wave 1 guardrails), and identity verification for identified users (SEC-13).


type IngestContext = {
  tenantId: string;
  environment: string;
  via: 'api_key' | 'site_key';
  siteId?: string;
  siteUuid?: string;
};

/** Read the secret API key if one was sent. JWTs (anon/user tokens) are ignored here. */
function readApiKey(req: Request): string | null {
  const header = req.headers.get('x-api-key')?.trim();
  if (header) return header;
  const auth = req.headers.get('authorization') ?? '';
  const bearer = auth.startsWith('Bearer ') ? auth.slice(7).trim() : '';
  // Supabase JWTs have three dot-separated parts; Marbee API keys don't.
  if (bearer && bearer.split('.').length !== 3) return bearer;
  return null;
}

async function authenticateApiKey(db: SupabaseClient, rawKey: string, scope: string): Promise<IngestContext> {
  const { data, error } = await db.rpc('verify_api_key', { p_raw_key: rawKey });
  if (error) {
    console.error('verify_api_key failed', error.message);
    throw new AuthError(500, 'Could not verify API key');
  }
  const row = Array.isArray(data) ? data[0] : null;
  if (!row) throw new AuthError(401, 'Invalid or revoked API key');
  const scopes: string[] = row.scopes ?? [];
  if (!scopes.includes(scope) && !scopes.includes('*')) throw new AuthError(403, `API key is missing the ${scope} scope`);
  return { tenantId: row.tenant_id, environment: row.environment ?? 'production', via: 'api_key' };
}

async function authenticateSiteKey(
  db: SupabaseClient,
  siteId: unknown,
  writeKey: unknown,
  origin: string | null,
): Promise<IngestContext> {
  if (typeof siteId !== 'string' || typeof writeKey !== 'string') {
    throw new AuthError(401, 'site_id and write_key are required');
  }
  const { data, error } = await db.rpc('resolve_ingest_site', {
    p_site_id: siteId, p_write_key: writeKey, p_origin: origin,
  });
  if (error) {
    console.error('resolve_ingest_site failed', error.message);
    throw new AuthError(500, 'Could not verify site key');
  }
  const r = data as { ok: boolean; reason?: string; tenant_id?: string; environment?: string; site_id?: string; site_uuid?: string };
  if (!r?.ok) {
    const status = r?.reason === 'invalid_key' ? 401 : 403;
    const message = r?.reason === 'origin_not_allowed'
      ? 'This website is not allowed to use this site key'
      : r?.reason === 'tenant_suspended' ? 'This workspace is suspended'
      : r?.reason?.startsWith('site_') ? 'Site is not active' : 'Invalid site key';
    throw new AuthError(status, message);
  }
  return { tenantId: r.tenant_id!, environment: r.environment ?? 'production', via: 'site_key', siteId: r.site_id, siteUuid: r.site_uuid };
}

/** API key if present, otherwise site key from the parsed body. */
async function authenticateIngest(
  req: Request,
  db: SupabaseClient,
  body: Record<string, unknown> | null,
  scope: string,
): Promise<IngestContext> {
  const apiKey = readApiKey(req);
  if (apiKey) return authenticateApiKey(db, apiKey, scope);
  return authenticateSiteKey(db, body?.site_id, body?.write_key, req.headers.get('origin'));
}

// --------------------------------------------------------------------------------------
// Rate limit — fixed window per isolate. A backstop against floods, not a billing meter.
// --------------------------------------------------------------------------------------
const windows = new Map<string, { start: number; count: number }>();

function rateLimited(key: string, max: number, windowMs = 60_000): boolean {
  const now = Date.now();
  const w = windows.get(key);
  if (!w || now - w.start >= windowMs) {
    windows.set(key, { start: now, count: 1 });
    if (windows.size > 10_000) windows.clear(); // bound memory
    return false;
  }
  w.count += 1;
  return w.count > max;
}

function clientIp(req: Request): string {
  return req.headers.get('cf-connecting-ip')
    ?? req.headers.get('x-forwarded-for')?.split(',')[0]?.trim()
    ?? 'unknown';
}

/** Reject oversized bodies before parsing (Content-Length when present). */
function tooLarge(req: Request, maxBytes: number): boolean {
  const len = Number(req.headers.get('content-length') ?? 0);
  return Number.isFinite(len) && len > maxBytes;
}

// ---- push-subscribe/index.ts ---------------------------------
// push-subscribe — website push SDK backend (D-022).
//
//   POST { action: 'config', site_id, write_key }            → public Firebase web config,
//        VAPID public key and prompt settings for this site's workspace (all public values).
//   POST { site_id, write_key, fcm_token, ecid?, browser?, os?, device?, permission_status?, old_token? }
//        → save / refresh this browser's subscription; sends the welcome push (server-side,
//          through the outbox) the first time a browser subscribes.
//   DELETE { site_id, write_key, fcm_token } → unsubscribe this browser.
//
// SEC-02: tenant/environment come ONLY from a verified site key (origin-checked) or a
// secret API key — never from the request. A browser can only be linked to a customer
// SERVER-SIDE: through its website anonymous id (ecid) in customer_identities, or by a
// caller holding a secret API key. A `customer_id` sent with a public site key is ignored,
// otherwise anyone could attach their own browser to someone else's notifications.
// Deploy with "Enforce JWT Verification" OFF: website visitors have no Supabase login.


const str = (v: unknown, max: number) => (typeof v === 'string' && v.trim().length > 0 ? v.trim().slice(0, max) : null);
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
// FCM registration tokens: URL-safe base64 + ':' / '-' / '_'.
const TOKEN_RE = /^[A-Za-z0-9:_\-]{20,4096}$/;

type Behavior = Record<string, unknown>;

serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: corsHeaders() });
  if (req.method !== 'POST' && req.method !== 'DELETE') return errorResponse('Method not allowed', 405);
  if (tooLarge(req, 16 * 1024)) return errorResponse('Payload too large', 413);

  try {
    const supabase = getServiceClient();
    const body = (await req.json().catch(() => null)) as Record<string, unknown> | null;
    if (!body || typeof body !== 'object' || Array.isArray(body)) return errorResponse('JSON body required', 400);

    const ctx = await authenticateIngest(req, supabase, body, 'events:write');
    const ip = clientIp(req);
    if (rateLimited(`push-sub:${ctx.siteId ?? ctx.tenantId}:${ip}`, 30)) return errorResponse('Rate limit exceeded', 429);

    const { data: provider } = await supabase.from('channel_providers').select('id, config, status')
      .eq('tenant_id', ctx.tenantId).eq('environment', ctx.environment).eq('channel', 'web_push')
      .eq('is_default', true).limit(1).maybeSingle();
    const cfg = (provider?.config ?? {}) as Record<string, unknown>;
    const behavior = (cfg.web_push ?? {}) as Behavior;

    // ---- public config for the SDK --------------------------------------------------
    if (body.action === 'config') {
      if (!provider || provider.status === 'disabled') return errorResponse('Web Push is not set up for this website', 404);
      const s = (k: string) => (typeof cfg[k] === 'string' ? String(cfg[k]).trim() : '');
      if (!s('api_key') || !s('project_id') || !s('sender_id') || !s('app_id') || !s('vapid_public_key')) {
        return errorResponse('Web Push is not fully configured for this website', 404);
      }
      return jsonResponse({
        firebase: {
          apiKey: s('api_key'),
          authDomain: s('auth_domain') || `${s('project_id')}.firebaseapp.com`,
          projectId: s('project_id'),
          messagingSenderId: s('sender_id'),
          appId: s('app_id'),
        },
        vapid_public_key: s('vapid_public_key'),
        prompt: {
          enabled: behavior.prompt_enabled !== false,
          delay_ms: Math.min(Math.max(Number(behavior.prompt_delay_ms ?? 4000) || 0, 0), 120000),
          title: String(behavior.prompt_title ?? 'Stay in the loop').slice(0, 120),
          message: String(behavior.prompt_message ?? 'Get timely updates in your browser.').slice(0, 300),
          accept_label: String(behavior.prompt_accept_label ?? 'Allow').slice(0, 40),
          dismiss_label: String(behavior.prompt_dismiss_label ?? 'Not now').slice(0, 40),
          icon_url: typeof behavior.default_icon_url === 'string' ? behavior.default_icon_url.slice(0, 500) : null,
        },
      });
    }

    const fcmToken = str(body.fcm_token, 4096);
    if (!fcmToken || !TOKEN_RE.test(fcmToken)) return errorResponse('fcm_token is required');

    if (req.method === 'DELETE') {
      const { data: gone } = await supabase.from('web_push_subscribers')
        .update({ subscription_status: 'inactive', token_invalidated_at: new Date().toISOString() })
        .eq('tenant_id', ctx.tenantId).eq('environment', ctx.environment).eq('fcm_token', fcmToken)
        .select('id');
      const ids = (gone ?? []).map((r: { id: string }) => r.id);
      if (ids.length) await supabase.from('channel_endpoints').update({ status: 'inactive' }).eq('tenant_id', ctx.tenantId).in('subscriber_id', ids);
      return jsonResponse({ success: true });
    }

    // Token rotated by the browser: retire the old one.
    const oldToken = str(body.old_token, 4096);
    if (oldToken && oldToken !== fcmToken && TOKEN_RE.test(oldToken)) {
      await supabase.from('web_push_subscribers')
        .update({ subscription_status: 'inactive', token_invalidated_at: new Date().toISOString() })
        .eq('tenant_id', ctx.tenantId).eq('environment', ctx.environment).eq('fcm_token', oldToken);
    }

    // Website anonymous id (analytics SDK: "mb_<uuid>"). Strictly validated, never "cleaned":
    // a value that fails the pattern is simply not used for linking or stored.
    const rawEcid = str(body.ecid, 200);
    const ecid = rawEcid && /^[A-Za-z0-9_.-]{8,200}$/.test(rawEcid) ? rawEcid : null;
    // Who is this browser? Only the server decides (see header).
    let customerId: string | null = null;
    if (ctx.via === 'api_key' && typeof body.customer_id === 'string' && UUID_RE.test(body.customer_id)) {
      const { data: c } = await supabase.from('customers').select('id')
        .eq('tenant_id', ctx.tenantId).eq('environment', ctx.environment).eq('id', body.customer_id).maybeSingle();
      customerId = c?.id ?? null;
    }
    if (!customerId && ecid) {
      const { data: ident } = await supabase.from('customer_identities').select('customer_id')
        .eq('tenant_id', ctx.tenantId).eq('environment', ctx.environment)
        .or(`ecid.eq.${ecid},anonymous_id.eq.${ecid}`)
        .not('customer_id', 'is', null).limit(1).maybeSingle();
      customerId = ident?.customer_id ?? null;
    }

    const { data: existing } = await supabase.from('web_push_subscribers').select('id, subscription_status, customer_id')
      .eq('tenant_id', ctx.tenantId).eq('environment', ctx.environment).eq('fcm_token', fcmToken).maybeSingle();

    const row: Record<string, unknown> = {
      tenant_id: ctx.tenantId,
      environment: ctx.environment,
      fcm_token: fcmToken,
      ecid,
      browser: str(body.browser, 100),
      os: str(body.os, 100),
      device: str(body.device, 50),
      permission_status: 'granted',
      subscription_status: 'active',
      token_invalidated_at: null,
      last_seen: new Date().toISOString(),
    };
    // Never un-link a known customer because this request couldn't identify them.
    if (customerId) row.customer_id = customerId;

    const { data, error } = await supabase.from('web_push_subscribers')
      .upsert(row, { onConflict: 'tenant_id,environment,fcm_token' })
      .select('id').single();
    if (error) {
      console.error('push-subscribe upsert failed', error.message);
      return errorResponse('Could not save subscription', 500);
    }

    const { data: endpoint } = await supabase.from('channel_endpoints').select('id')
      .eq('tenant_id', ctx.tenantId).eq('subscriber_id', data.id).eq('channel', 'web_push').limit(1).maybeSingle();
    if (endpoint) {
      await supabase.from('channel_endpoints').update({ status: 'active', address: fcmToken }).eq('id', endpoint.id);
    } else {
      await supabase.from('channel_endpoints').insert({
        tenant_id: ctx.tenantId, environment: ctx.environment, subscriber_id: data.id,
        channel: 'web_push', provider: 'firebase', address: fcmToken, status: 'active',
      });
    }

    // Welcome push — first subscription of this browser only; idempotent by device.
    const isNew = !existing || existing.subscription_status !== 'active';
    let welcome = false;
    if (isNew && behavior.welcome_enabled !== false && provider && provider.status !== 'disabled') {
      const { data: q, error: qErr } = await supabase.rpc('enqueue_web_push_internal', {
        p_tenant_id: ctx.tenantId,
        p_environment: ctx.environment,
        p_customer_ids: [],
        p_subscriber_ids: [data.id],
        p_content: {
          title: String(behavior.welcome_title ?? 'Notifications enabled').slice(0, 200),
          body: String(behavior.welcome_body ?? 'You will receive updates from us here.').slice(0, 1000),
          click_url: typeof behavior.welcome_click_url === 'string' ? behavior.welcome_click_url : '/',
          icon_url: typeof behavior.default_icon_url === 'string' ? behavior.default_icon_url : undefined,
          tag: 'marbee-welcome',
        },
        p_idempotency_key: `welcome:${data.id}`,
        p_delivery_name: 'Welcome notification',
      });
      if (qErr) console.error('welcome enqueue failed', qErr.message);
      welcome = Number((q as { queued?: number } | null)?.queued ?? 0) > 0;
    }

    return jsonResponse({ success: true, subscribed: true, welcome_queued: welcome });
  } catch (err) {
    if (err instanceof AuthError) return errorResponse(err.message, err.status);
    console.error('push-subscribe unhandled', err instanceof Error ? err.message : err);
    return errorResponse('Internal error', 500);
  }
});
